"""ОБД «Мемориал», Шуті з Вороньків (08.11.2026): донесення з іменами батьків → картки дерева.
Скани — зі звітів reportpdf ОБД (сторінка 2 PDF, оригінальна роздільність ОБД); рамка — координати рядка з ОБД (getimageinfo)."""
import json, shutil
from PIL import Image

R = '/home/claude/rid-shutykh/'
MAN = R + 'seed/import/manifest.json'
IMP = R + 'seed/import/'
SRC = '/tmp/obd/pdf/img/'
m = json.load(open(MAN)); have = {it.get('key') for it in m}

def put(src, name):
    im = Image.open(src).convert('RGB'); im.save(IMP + name, quality=92)
    t = im.copy(); t.thumbnail((420, 420)); t.save(IMP + name.replace('.jpg', '-t.jpg'), quality=85)

def mark(y, h):
    return [{'p': 0, 'x': 0.0, 'y': round(max(0, y - 0.006), 4), 'w': 1.0, 'h': round(h + 0.012, 4)}]

U = 'https://obd-memorial.ru/html/info.htm?id='
