# Історія роду
m = json.load(open(MAN)); have = {it.get('key') for it in m}
if 'obd2-text-history' not in have:
    H = [x for x in m if x['kind'] == 'text' and x.get('id') == 'history'][-1]; md = H['value']['md']
    A = 'Чиї вони сини, донесення не кажуть; шукати їхні метрики (1911, 1922).'
    B = A + (' У тих самих списках втрат Ново-Басанського райвійськкомату (у них записані й родичі загиблих) знайшлися ще наші: '
             '«Шутый Николай Гордеевич», 1917 р. н., старший сержант, убитий 28.08.1942, — батьком записаний «Шутый Гордей Павлович» з Вороньків ([[d:obd51215637|донесення]]; Є припущення, що це син [[p:s20_hordii_p|Гордія Павловича]] і брат [[p:mykhailo_hsh24|Михайла]] — [[p:mykola_hp17|Микола]]); '
             '«Шутий Федор Андреевич», 1925 р. н., з 482-го саперного батальйону, — мати «Ульяна Михайловна» з Вороньків ([[d:obd55472888|донесення]]; Є припущення, що це син [[p:andrii_f|Андрія Федоровича]] — [[p:fedir_af25|Федір]]); '
             'у [[p:mykhailo_mi16|Михайла Максимовича]] (загинув 28.08.1941 біля Каховки) батьком записаний Максим Іванович ([[d:obd58466125|донесення]]). '
             'Загалом в ОБД «Мемориал» — кілька десятків записів про загиблих і зниклих Шутих з Вороньків; усі вони в «Базі», а хто з них чий син — ще треба встановити.')
    if A in md:
        v = dict(H['value']); v['md'] = md.replace(A, B, 1)
        m.append({'key': 'obd2-text-history', 'kind': 'text', 'id': 'history', 'value': v})
        json.dump(m, open(MAN, 'w'), ensure_ascii=False, indent=1); print('історію оновлено')
